<script setup>
import{ref,computed,onMounted,onUnmounted}from'vue';import{api}from'../services/api.js';import{auth}from'../stores/auth.js';import UiState from'../components/UiState.vue';import BaseModal from'../components/BaseModal.vue'
const now=ref(new Date()),status=ref(null),working=ref([]),recent=ref([]),intervals=ref([]),myIntervals=ref([]),payroll=ref([]),operators=ref([]),excessRows=ref([]),operatorId=ref(''),showExcess=ref(false),tab=ref('punch'),code=ref(''),busy=ref(false),loading=ref(false),error=ref(''),success=ref(''),search=ref(''),roleFilter=ref(''),modal=ref(null),incidentUserId=ref(null),editValue=ref(''),settings=ref({exit_display_mode:'real'})
const today=new Date(),iso=d=>d.toISOString().slice(0,10),range=ref({from:iso(new Date(today.getTime()-30*86400000)),to:iso(today)})
const supervisor=computed(()=>['Administrador','Supervisor'].includes(auth.user.role_name))
const hasPermission=permission=>!!auth.user?.permissions?.includes(permission)
const manager=computed(()=>supervisor.value||!!auth.user.time_clock_management_enabled||hasPermission('time_clock.manage'))
const canPayroll=computed(()=>manager.value&&hasPermission('time_clock.payroll'))
const canSettings=computed(()=>manager.value&&hasPermission('time_clock.settings'))
const formatTime=v=>v?new Intl.DateTimeFormat('ca-ES',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'}).format(new Date(v)):'-'
const duration=m=>`${Math.floor(Number(m||0)/60)} h ${String(Math.abs(Number(m||0)%60)).padStart(2,'0')} min`
const clock=computed(()=>new Intl.DateTimeFormat('ca-ES',{dateStyle:'full',timeStyle:'medium',timeZone:'Europe/Madrid'}).format(now.value))
const filteredPayroll=computed(()=>payroll.value.filter(x=>(!search.value||x.name.toLowerCase().includes(search.value.toLowerCase())||x.email.toLowerCase().includes(search.value.toLowerCase()))&&(!roleFilter.value||String(x.roleId)===roleFilter.value)))
let timer
async function loadStatus(){status.value=await api.get('/time-clock/status')}
async function loadWorking(){working.value=await api.get('/time-clock/working')}
async function loadMyControl(){loading.value=true;error.value='';try{myIntervals.value=await api.get(`/time-clock/my-control?from=${range.value.from}&to=${range.value.to}`)}catch(e){error.value=e.message}finally{loading.value=false}}
function shownMinutes(row){return row.displayTotalMinutes??row.totalMinutes}
function mobile(){return/mobi|android|iphone|ipad/i.test(navigator.userAgent)||matchMedia('(pointer: coarse)').matches}
function locate(){return new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy}),()=>reject(new Error('Cal permetre la ubicacio per fitxar des del mobil')),{enableHighAccuracy:true,timeout:12000}):reject(new Error('Aquest dispositiu no permet obtenir la ubicacio')))}
async function punch(){if(busy.value)return;busy.value=true;error.value='';success.value='';try{const isMobile=mobile(),location=isMobile?await locate():{};const result=await api.post('/time-clock/punch',{code:auth.user.multi_time_clock_enabled?code.value:undefined,is_mobile:isMobile,...location});success.value=result.message;code.value='';await loadStatus();if(manager.value)await loadWorking();if(tab.value==='my-control')await loadMyControl()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadRecent(){loading.value=true;try{recent.value=await api.get('/time-clock/recent')}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadControl(){loading.value=true;error.value='';try{intervals.value=await api.get(`/time-clock/admin?from=${range.value.from}&to=${range.value.to}&search=${encodeURIComponent(search.value)}`)}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadPayroll(){loading.value=true;error.value='';try{payroll.value=await api.get(`/time-clock/payroll-summary?from=${range.value.from}&to=${range.value.to}`)}catch(e){error.value=e.message}finally{loading.value=false}}
async function toggleExcess(){showExcess.value=!showExcess.value;if(showExcess.value&&!operators.value.length){operators.value=await api.get('/time-clock/multi-operators');operatorId.value=String(operators.value[0]?.id||'');if(operatorId.value)await loadExcess()}}
async function loadExcess(){if(!operatorId.value)return;excessRows.value=await api.get(`/time-clock/multi-excess?operator_id=${operatorId.value}&from=${range.value.from}&to=${range.value.to}`)}
async function chooseTab(value){tab.value=value;if(value==='my-control')await loadMyControl();if(value==='working')await loadWorking();if(value==='recent')await loadRecent();if(value==='control')await loadControl();if(value==='payroll')await loadPayroll();if(value==='settings')settings.value=await api.get('/time-clock/settings')}
function localValue(v){const d=new Date(v),parts=new Intl.DateTimeFormat('sv-SE',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Madrid'}).format(d);return parts.replace(' ','T')}
function openEdit(interval,type){const entry=type==='in'?interval.entry:interval.exit;modal.value={kind:'edit',interval,entry};editValue.value=localValue(entry.punched_at)}
function openExit(interval){if(modal.value?.kind==='incidents')incidentUserId.value=modal.value.row.userId;modal.value={kind:'exit',interval,entry:interval.entry};editValue.value=localValue(new Date(new Date(interval.entry.punched_at).getTime()+8*3600000))}
function closeModal(){if(modal.value?.kind==='incidents'){modal.value=null;incidentUserId.value=null;loadPayroll();return}if(incidentUserId.value){const row=payroll.value.find(x=>x.userId===incidentUserId.value);modal.value=row?.incompleteDays?{kind:'incidents',row}:null;if(!modal.value)incidentUserId.value=null}else modal.value=null}
async function saveModal(){if(busy.value)return;busy.value=true;error.value='';try{if(modal.value.kind==='edit')await api.patch('/time-clock/entries/'+modal.value.entry.id,{punched_at:editValue.value});else await api.post('/time-clock/entries/'+modal.value.entry.id+'/exit',{punched_at:editValue.value});modal.value=null;await Promise.all([loadControl(),loadPayroll()]);closeModal()}catch(e){error.value=e.message}finally{busy.value=false}}
function showLocation(entry,label){modal.value={kind:'location',entry,label}}
function mapUrl(e,external=false){const lat=Number(e.location_lat),lng=Number(e.location_lng);return external?`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lng}#map=18/${lat}/${lng}`:`https://www.openstreetmap.org/export/embed.html?bbox=${lng-.003}%2C${lat-.002}%2C${lng+.003}%2C${lat+.002}&layer=mapnik&marker=${lat}%2C${lng}`}
async function saveSettings(){busy.value=true;try{settings.value=await api.patch('/time-clock/settings',settings.value);success.value='Configuracio desada.'}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportFile(kind){await api.download(`/time-clock/${kind==='control'?'admin/export':'payroll-summary/export'}?from=${range.value.from}&to=${range.value.to}&search=${encodeURIComponent(search.value)}${roleFilter.value?'&role_id='+roleFilter.value:''}`,`${kind==='control'?'control-horari':'hores-a-pagar'}-${range.value.from}-${range.value.to}.xlsx`)}
onMounted(async()=>{timer=setInterval(()=>now.value=new Date(),1000);await loadStatus();if(manager.value)await loadWorking()});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="time-clock-page"><div class="tabs time-tabs" role="tablist"><button :class="{active:tab==='punch'}" @click="chooseTab('punch')">Fitxar</button><button v-if="!manager" :class="{active:tab==='my-control'}" @click="chooseTab('my-control')">El meu control horari</button><button v-if="manager" :class="{active:tab==='working'}" @click="chooseTab('working')">Persones treballant</button><button v-if="manager&&auth.user.multi_time_clock_enabled" :class="{active:tab==='recent'}" @click="chooseTab('recent')">Ultims 4 dies</button><button v-if="canPayroll" :class="{active:tab==='payroll'}" @click="chooseTab('payroll')">Hores a pagar</button><button v-if="manager" :class="{active:tab==='control'}" @click="chooseTab('control')">Control horari</button><button v-if="canSettings" :class="{active:tab==='settings'}" @click="chooseTab('settings')">Configuracio</button></div>
<div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="success" class="alert success" role="status">{{success}}</div>
<div v-if="tab==='punch'" class="card punch-card"><p class="eyebrow">Fitxatge de jornada</p><h2>{{clock}}</h2><span class="badge" :class="status?.working?'success':'neutral'">{{status?.working?'Jornada iniciada':'Fora de jornada'}}</span><label v-if="auth.user.multi_time_clock_enabled">Codi del treballador<input v-model="code" maxlength="40" autofocus @keyup.enter="punch"></label><button class="button primary punch-button" :disabled="busy||(auth.user.multi_time_clock_enabled&&!code)" @click="punch">{{busy?'Registrant...':status?.working&&!auth.user.multi_time_clock_enabled?'Finalitzar jornada':'Iniciar / finalitzar jornada'}}</button></div>
<div v-else-if="tab==='my-control'"><div class="filters time-filters"><label>Data inicial<input v-model="range.from" type="date"></label><label>Data final<input v-model="range.to" type="date"></label><button class="button primary" @click="loadMyControl">Actualitzar</button></div><UiState :loading="loading" :empty="!myIntervals.length" empty-text="No hi ha fitxatges en aquest interval."><div class="table-wrap"><table class="time-table"><thead><tr><th>Data</th><th>Entrada</th><th>Sortida</th><th>Total</th><th>Estat</th></tr></thead><tbody><tr v-for="row in myIntervals" :key="row.entry.id" :class="{issue:row.incomplete}"><td>{{row.workDate}}</td><td>{{formatTime(row.entry.punched_at)}}</td><td>{{row.exit?formatTime(row.displayExitAt||row.exit.punched_at):'Incompleta'}}</td><td>{{duration(shownMinutes(row))}}</td><td><span class="badge" :class="row.incomplete?'warning':'success'">{{row.incomplete?'Incompleta':'Completa'}}</span></td></tr></tbody></table></div></UiState></div>
<UiState v-else-if="tab==='working'" :loading="loading" :empty="!working.length" empty-text="No hi ha persones dins de jornada, de vacances o de baixa."><div class="toolbar"><h2>Persones treballant</h2><button class="button secondary" @click="loadWorking">Actualitzar</button></div><div class="table-wrap"><table><thead><tr><th>Empleat</th><th>Entrada</th><th>Sortida</th><th>Estat</th></tr></thead><tbody><tr v-for="row in working" :key="row.id"><td data-label="Empleat">{{row.user_name}}<small v-if="row.reason">{{row.reason}}</small></td><td data-label="Entrada">{{row.status==='working'?formatTime(row.punched_at):'-'}}</td><td data-label="Sortida">-</td><td data-label="Estat"><span class="badge" :class="row.status==='working'?'success':'warning'">{{row.status==='working'?'Jornada activa':row.status==='vacation'?'De vacances':'De baixa'}}</span></td></tr></tbody></table></div></UiState>
<UiState v-else-if="tab==='recent'" :loading="loading" :empty="!recent.length" empty-text="No hi ha registres dels ultims quatre dies."><div class="table-wrap"><table><thead><tr><th>Data</th><th>Empleat</th><th>Correu</th><th>Entrada</th><th>Sortida</th><th>Estat</th><th>Temps</th></tr></thead><tbody><tr v-for="row in recent" :key="row.entry.id"><td>{{row.workDate}}</td><td>{{row.userName}}</td><td>{{row.email}}</td><td>{{formatTime(row.entry.punched_at)}}</td><td>{{formatTime(row.exit?.punched_at)}}</td><td><span class="badge" :class="row.incomplete?'warning':'success'">{{row.incomplete?'Incompleta':'Completa'}}</span></td><td>{{duration(row.totalMinutes)}}</td></tr></tbody></table></div></UiState>
<div v-else-if="tab==='control'||tab==='payroll'"><div class="filters time-filters"><label>Data inicial<input v-model="range.from" type="date"></label><label>Data final<input v-model="range.to" type="date"></label><label v-if="tab==='control'">Cercador<input v-model="search" placeholder="Nom, correu o data"></label><button class="button primary" @click="tab==='control'?loadControl():loadPayroll()">{{tab==='control'?'Actualitzar':'Calcular hores'}}</button><button class="button secondary" @click="exportFile(tab)">Exportar Excel</button><button v-if="tab==='control'" class="button secondary" @click="toggleExcess">Exces 8h multifitxatge</button></div>
 <section v-if="tab==='control'&&showExcess" class="card excess-panel"><h2>Exces sobre 8h per multifitxatge</h2><div class="filters"><label>Operador<select v-model="operatorId" @change="loadExcess"><option v-for="op in operators" :key="op.id" :value="String(op.id)">{{op.name}}</option></select></label><button class="button secondary" @click="loadExcess">Consultar</button></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Empleat</th><th>Temps treballat</th><th>Exces real</th><th>Extra computada</th></tr></thead><tbody><tr v-for="row in excessRows" :key="row.date+'-'+row.userId"><td>{{row.date}}</td><td>{{row.name}}</td><td>{{duration(row.totalMinutes)}}</td><td>{{duration(row.realExtraMinutes)}}</td><td>{{duration(row.computedExtraMinutes)}}</td></tr></tbody></table></div></section>
 <template v-if="tab==='control'"><UiState :loading="loading" :empty="!intervals.length" empty-text="No hi ha fitxatges en aquest interval."><div class="table-wrap"><table class="time-table"><thead><tr><th>Data</th><th>Empleat</th><th>Entrada</th><th>Sortida</th><th>Ubicacio</th></tr></thead><tbody><tr v-for="row in intervals" :key="row.entry.id" :class="{issue:row.incomplete}"><td>{{row.workDate}}</td><td>{{row.userName}}<small>{{row.email}}</small></td><td>{{formatTime(row.entry.punched_at)}} <button v-if="supervisor" class="link" @click="openEdit(row,'in')">Editar</button></td><td><template v-if="row.exit">{{formatTime(row.displayExitAt||row.exit.punched_at)}} <button v-if="supervisor" class="link" @click="openEdit(row,'out')">Editar</button></template><button v-else-if="supervisor" class="button secondary compact" @click="openExit(row)">Informar hora</button><span v-else>Incompleta</span></td><td><button v-if="row.entry.location_lat" class="link" @click="showLocation(row.entry,'Entrada')">Entrada</button> <button v-if="row.exit?.location_lat" class="link" @click="showLocation(row.exit,'Sortida')">Sortida</button><span v-if="!row.entry.location_lat&&!row.exit?.location_lat">Sense ubicacio</span></td></tr></tbody></table></div></UiState></template>
 <template v-else><div class="payroll-toolbar"><label class="search"><input v-model="search" type="search" placeholder="Cercar per nom o correu"></label><label>Rol<select v-model="roleFilter"><option value="">Tots</option><option v-for="role in [...new Map(payroll.map(x=>[x.roleId,x.roleName])).entries()]" :key="role[0]" :value="String(role[0])">{{role[1]}}</option></select></label></div><UiState :loading="loading" :empty="!filteredPayroll.length" empty-text="No hi ha hores pagables."><div class="table-wrap"><table><thead><tr><th>Empleat</th><th>Dies</th><th>Dia</th><th>Nit</th><th>Fitxades</th><th>Ordinaries</th><th>Extra real</th><th>Extra computada</th><th>Total a pagar</th><th>Incidencies</th></tr></thead><tbody><tr v-for="row in filteredPayroll" :key="row.userId"><td>{{row.name}}<small>{{row.email}}</small></td><td>{{row.payableDays}}</td><td>{{duration(row.dayMinutes)}}</td><td>{{duration(row.nightMinutes)}}</td><td>{{duration(row.workedMinutes)}}</td><td>{{duration(row.ordinaryMinutes)}}</td><td>{{duration(row.realExtraMinutes)}}</td><td>{{duration(row.computedExtraMinutes)}}</td><td><strong>{{duration(row.payableMinutes)}}</strong></td><td><button v-if="row.incompleteDays&&supervisor" class="link" @click="modal={kind:'incidents',row}">{{row.incompleteDays}} {{row.incompleteDays===1?'dia incomplet':'dies incomplets'}}</button><span v-else>{{row.incompleteDays||'-'}}</span></td></tr></tbody></table></div></UiState></template></div>
<form v-else-if="tab==='settings'" class="card settings" @submit.prevent="saveSettings"><h2>Sortida mostrada</h2><label><select v-model="settings.exit_display_mode"><option value="real">Sortida real</option><option value="theoretical_8h">Sortida teorica de 8 hores</option></select></label><button class="button primary" :disabled="busy">Desar</button></form>
<BaseModal :open="!!modal" :title="modal?.kind==='location'?'Ubicacio':modal?.kind==='incidents'?'Jornades incompletes':'Informar data i hora'" @close="closeModal"><template v-if="modal?.kind==='location'"><iframe class="osm-map" :src="mapUrl(modal.entry)" title="Mapa OpenStreetMap"></iframe><p>{{modal.entry.location_lat}}, {{modal.entry.location_lng}}</p><a class="button secondary" :href="mapUrl(modal.entry,true)" target="_blank" rel="noopener">Obrir en una pestanya nova</a></template><template v-else-if="modal?.kind==='incidents'"><div v-for="incident in modal.row.incidents" :key="incident.date" class="incident-item"><strong>{{incident.date}}</strong><div v-for="line in incident.intervals" :key="line.entry.id">Entrada {{formatTime(line.entry.punched_at)}} <button class="button secondary compact" @click="openExit(line)">Informar hora final</button></div></div></template><label v-else>Data i hora<input v-model="editValue" type="datetime-local" required></label><template #actions><button class="button secondary" @click="closeModal">Cancel.lar</button><button v-if="modal&&!['location','incidents'].includes(modal.kind)" class="button primary" :disabled="busy" @click="saveModal">{{busy?'Desant...':'Desar'}}</button></template></BaseModal></section></template>